-- Portal sign-in with one-time codes (Phase 1 slice 1.8; ADR-0026, owner decision P1): portal
-- users join identity.account without a username, their sealed addresses, the codes sent to
-- them and each tenant's settings. Generated by prisma migrate diff, then the hand-written
-- CHECKs, grants and row-level security at the end.
-- AlterTable
ALTER TABLE "identity"."account" ALTER COLUMN "username" DROP NOT NULL;

-- CreateTable
CREATE TABLE "identity"."portal_sign_in_settings" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "methods" VARCHAR(16)[],
    "country_calling_code" VARCHAR(4),
    "version" INTEGER NOT NULL,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "portal_sign_in_settings_pkey" PRIMARY KEY ("tenant_id")
);

-- CreateTable
CREATE TABLE "identity"."portal_contact" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "account_id" UUID NOT NULL,
    "kind" VARCHAR(16) NOT NULL,
    "lookup_hash" BYTEA NOT NULL,
    "sealed" BYTEA NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "portal_contact_pkey" PRIMARY KEY ("tenant_id","account_id","kind")
);

-- CreateTable
CREATE TABLE "identity"."portal_code" (
    "id" UUID NOT NULL,
    "tenant_id" VARCHAR(32) NOT NULL,
    "kind" VARCHAR(16) NOT NULL,
    "lookup_hash" BYTEA NOT NULL,
    "code_hash" BYTEA NOT NULL,
    "failures" SMALLINT NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,
    "spent_at" TIMESTAMPTZ(3),

    CONSTRAINT "portal_code_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "portal_contact_tenant_id_kind_lookup_hash_key" ON "identity"."portal_contact"("tenant_id", "kind", "lookup_hash");

-- CreateIndex
CREATE INDEX "portal_code_tenant_id_expires_at_idx" ON "identity"."portal_code"("tenant_id", "expires_at");

-- CreateIndex
CREATE UNIQUE INDEX "portal_code_tenant_id_id_key" ON "identity"."portal_code"("tenant_id", "id");

-- AddForeignKey
ALTER TABLE "identity"."portal_contact" ADD CONSTRAINT "portal_contact_account_fkey" FOREIGN KEY ("tenant_id", "account_id") REFERENCES "identity"."account"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- Hand-written: a portal user is the only account without a username, and the only one whose
-- credential is a one-time code (ADR-0026); a directory account always has its subject, a
-- portal account never has one.
ALTER TABLE "identity"."account"
  DROP CONSTRAINT "account_source_check",
  DROP CONSTRAINT "account_directory_subject_check",
  ADD CONSTRAINT "account_source_check" CHECK ("source" IN ('directory', 'local', 'one-time-code')),
  ADD CONSTRAINT "account_population_source_check" CHECK (("population" = 'portal-user') = ("source" = 'one-time-code')),
  ADD CONSTRAINT "account_population_username_check" CHECK (("population" = 'portal-user') = ("username" IS NULL)),
  ADD CONSTRAINT "account_directory_subject_check" CHECK ("source" <> 'directory' OR "subject" IS NOT NULL),
  ADD CONSTRAINT "account_portal_subject_check" CHECK ("source" <> 'one-time-code' OR "subject" IS NULL);

ALTER TABLE "identity"."portal_sign_in_settings"
  ADD CONSTRAINT "portal_sign_in_settings_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "portal_sign_in_settings_methods_check" CHECK (
    "methods" IS NOT NULL AND "methods" <@ ARRAY['email', 'mobile']::VARCHAR(16)[] AND cardinality("methods") <= 2
    -- Each method once: {email,email} is refused.
    AND cardinality(array_positions("methods", 'email'::VARCHAR(16))) <= 1
    AND cardinality(array_positions("methods", 'mobile'::VARCHAR(16))) <= 1
  ),
  ADD CONSTRAINT "portal_sign_in_settings_country_calling_code_check" CHECK (
    "country_calling_code" IS NULL OR "country_calling_code" ~ '^[1-9][0-9]{0,3}$'
  ),
  ADD CONSTRAINT "portal_sign_in_settings_version_check" CHECK ("version" >= 1);

ALTER TABLE "identity"."portal_contact"
  ADD CONSTRAINT "portal_contact_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "portal_contact_kind_check" CHECK ("kind" IN ('email', 'mobile')),
  ADD CONSTRAINT "portal_contact_lookup_hash_check" CHECK (octet_length("lookup_hash") = 32),
  -- Sealed: 29 bytes of format, IV and tag, then at most 254 bytes of address.
  ADD CONSTRAINT "portal_contact_sealed_check" CHECK (octet_length("sealed") BETWEEN 30 AND 283);

ALTER TABLE "identity"."portal_code"
  ADD CONSTRAINT "portal_code_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "portal_code_kind_check" CHECK ("kind" IN ('email', 'mobile')),
  ADD CONSTRAINT "portal_code_lookup_hash_check" CHECK (octet_length("lookup_hash") = 32),
  ADD CONSTRAINT "portal_code_code_hash_check" CHECK (octet_length("code_hash") = 32),
  ADD CONSTRAINT "portal_code_failures_check" CHECK ("failures" BETWEEN 0 AND 5),
  ADD CONSTRAINT "portal_code_expiry_check" CHECK ("expires_at" > "created_at"),
  ADD CONSTRAINT "portal_code_spent_at_check" CHECK ("spent_at" IS NULL OR "spent_at" >= "created_at");

-- Grants. An address is inserted once and never changed (erasure destroys its subject key); a
-- code counts its wrong answers, is spent once and is pruned after it expires.
GRANT SELECT, INSERT, UPDATE ("methods", "country_calling_code", "version", "updated_at") ON TABLE "identity"."portal_sign_in_settings" TO "phoenix_app";
GRANT SELECT, INSERT ON TABLE "identity"."portal_contact" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("failures", "spent_at"), DELETE ON TABLE "identity"."portal_code" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy.
ALTER TABLE "identity"."portal_sign_in_settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."portal_sign_in_settings" FORCE ROW LEVEL SECURITY;
CREATE POLICY "portal_sign_in_settings_tenant_isolation" ON "identity"."portal_sign_in_settings"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
ALTER TABLE "identity"."portal_contact" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."portal_contact" FORCE ROW LEVEL SECURITY;
CREATE POLICY "portal_contact_tenant_isolation" ON "identity"."portal_contact"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
ALTER TABLE "identity"."portal_code" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."portal_code" FORCE ROW LEVEL SECURITY;
CREATE POLICY "portal_code_tenant_isolation" ON "identity"."portal_code"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
